helper_before:
const goToRelationSettings = async (page) => {
  const listResponse = page.waitForResponse(
    (response) => response.url().includes('/glossaryTermRelationSettings/relationTypes') && response.request().method() === 'GET'
  );
  await page.goto(RELATION_SETTINGS_ROUTE);
  await listResponse;
  await expect(page.getByTestId('relation-types-table')).toBeVisible();
};
